          "text": "Our objective in this study was to determine whether the decision to manage a contralateral hydrocele in cases of neonatal testicular torsion solely through a scrotal approach is safe and effective. [PATIENTS AND METHOD] We reviewed all cases of neonatal testicular torsion occurring at our institution between the years 1999 and 2006.",
